SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE IF NOT EXISTS checkout_sessions (
    id                  INT AUTO_INCREMENT PRIMARY KEY,
    buyer_id            INT         NOT NULL,
    status              VARCHAR(16) NOT NULL DEFAULT 'PENDING',   -- PENDING/PAID/FAILED/EXPIRED
    payment_method      VARCHAR(16) NOT NULL,                     -- VNPAY/MOMO
    total_amount_minor  INT         NOT NULL,
    created_at          DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at          DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    INDEX idx_cs_buyer (buyer_id)
);

CREATE TABLE IF NOT EXISTS orders (
    id                         INT AUTO_INCREMENT PRIMARY KEY,
    checkout_session_id        INT         NOT NULL,
    buyer_id                   INT         NOT NULL,
    shop_id                    INT         NOT NULL,
    status                     VARCHAR(16) NOT NULL DEFAULT 'PENDING', -- PENDING/CONFIRMED/SHIPPING/DELIVERED/COMPLETED/CANCELLED
    shipping_address_snapshot  JSON        NOT NULL,
    subtotal_minor             INT         NOT NULL,
    shipping_fee_minor         INT         NOT NULL DEFAULT 0,
    total_minor                INT         NOT NULL,
    created_at                 DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    updated_at                 DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6),
    CONSTRAINT fk_orders_session FOREIGN KEY (checkout_session_id) REFERENCES checkout_sessions (id),
    INDEX idx_orders_session (checkout_session_id),
    INDEX idx_orders_buyer (buyer_id),
    INDEX idx_orders_shop (shop_id)
);

CREATE TABLE IF NOT EXISTS order_items (
    id                           INT AUTO_INCREMENT PRIMARY KEY,
    order_id                     INT          NOT NULL,
    variant_id                   INT          NOT NULL,
    product_name_snapshot        VARCHAR(200) NOT NULL,
    variant_attributes_snapshot  JSON         NULL,
    unit_price_minor             INT          NOT NULL,
    quantity                     INT          NOT NULL,
    subtotal_minor               INT          NOT NULL,
    CONSTRAINT fk_oi_order FOREIGN KEY (order_id) REFERENCES orders (id),
    INDEX idx_oi_order (order_id),
    INDEX idx_oi_variant (variant_id)
);

CREATE TABLE IF NOT EXISTS payments (
    id                       INT AUTO_INCREMENT PRIMARY KEY,
    checkout_session_id      INT          NOT NULL UNIQUE,
    provider                 VARCHAR(16)  NOT NULL,
    provider_transaction_id  VARCHAR(255) NULL,
    amount_minor             INT          NOT NULL,
    status                   VARCHAR(16)  NOT NULL DEFAULT 'PENDING', -- PENDING/SUCCEEDED/FAILED
    paid_at                  DATETIME(6)  NULL,
    created_at               DATETIME(6)  NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    CONSTRAINT fk_pay_session FOREIGN KEY (checkout_session_id) REFERENCES checkout_sessions (id)
);

